      {
        "type": "multiclass",
        "instruction": "Choose the service that means the carrier driver collects the outgoing parcel from the sender’s named pickup point.",
        "candidates": [
          {
            "id": "depot_drop_off",
            "description": "The sender carries the parcel to the carrier depot for scanning."
          },
